#define SHADER_NAME bloom-vertex


        #ifdef GL_ES // This checks if it is WebGL1
        #define in attribute
        #define out varying
        #endif
        precision highp float;

in vec2 aPosition;
out vec2 vTextureCoord;

uniform highp vec4 uInputSize;
uniform vec4 uOutputFrame;
uniform vec4 uOutputTexture;

vec4 filterVertexPosition( void ) {
  vec2 position = aPosition * uOutputFrame.zw + uOutputFrame.xy;
  position.x = position.x * (2.0 / uOutputTexture.x) - 1.0;
  position.y = position.y * (2.0 * uOutputTexture.z / uOutputTexture.y) - uOutputTexture.z;
  return vec4(position, 0.0, 1.0);
}

vec2 filterTextureCoord( void ) {
  return aPosition * (uOutputFrame.zw * uInputSize.zw);
}

void main(void) {
  gl_Position = filterVertexPosition();
  vTextureCoord = filterTextureCoord();
}

#define SHADER_NAME bloom-fragment


        #ifdef GL_ES // This checks if it is WebGL1
        #define in varying
        #define finalColor gl_FragColor
        #define texture texture2D
        #endif
        precision mediump float;

in vec2 vTextureCoord;


uniform sampler2D uTexture;
// Pixi's cropped filter-input dimensions in logical pixels, not the canvas.
uniform highp vec4 uInputSize;
uniform float uStrength;
uniform float uThreshold;

vec3 brightPass(vec2 uv) {
  vec3 c = texture(uTexture, uv).rgb;
  float luma = dot(c, vec3(0.2126, 0.7152, 0.0722));
  return c * max(luma - uThreshold, 0.0) / max(1.0 - uThreshold, 0.0001);
}

void main(void) {
  vec4 base = texture(uTexture, vTextureCoord);

  // Nine taps on a widening cross. Enough for a soft halo, cheap enough to run
  // every frame on a phone.
  vec3 bleed = vec3(0.0);
  bleed += brightPass(vTextureCoord) * 0.24;
  for (int i = 1; i <= 4; i++) {
    float o = float(i) * 1.6;
    float w = 0.19 / float(i);
    bleed += brightPass(vTextureCoord + vec2( o, 0.0) * uInputSize.zw) * w;
    bleed += brightPass(vTextureCoord + vec2(-o, 0.0) * uInputSize.zw) * w;
    bleed += brightPass(vTextureCoord + vec2(0.0,  o) * uInputSize.zw) * w;
    bleed += brightPass(vTextureCoord + vec2(0.0, -o) * uInputSize.zw) * w;
  }

  finalColor = vec4(base.rgb + bleed * uStrength, base.a);
}

